(function(root){
const membership=(p,a)=>p.armies.find(x=>x.army===a.id);
function availableOptions(p,a){return p.options.filter(o=>(!o.availableIn||o.availableIn.includes(a.name))&&(!o.unavailableIn||!o.unavailableIn.includes(a.name)));}
function requiredOptions(p,a){return(p.requiredOptions||[]).filter(o=>!o.in||o.in.some(group=>group.includes(a.name)));}
function configuration(p,a,ids=[]){const options=availableOptions(p,a);const required=requiredOptions(p,a);const chosen=options.filter(o=>ids.includes(o.id)||required.some(r=>r.name===o.name));const groups=new Set();for(const o of chosen){if(o.chooseOneKey){if(groups.has(o.chooseOneKey))throw Error('Choose only one option in each equipment group.');groups.add(o.chooseOneKey);}}const missing=required.filter(r=>!chosen.some(o=>o.name===r.name));return {options:[...chosen,...missing],points:p.points+[...chosen,...missing].reduce((s,o)=>s+o.points,0)};}
const allEntries=r=>[...(r.warbands||[]).flatMap(w=>[w.hero,...w.entries]),...(r.unassigned||[])];
const warriorCount=w=>w.entries.reduce((n,e)=>n+e.quantity,0);
function capacity(w,a,data){const p=data.profiles.find(p=>p.id===w.hero.profile);return data.capacities[membership(p,a)?.tier]??null;}
function entry(p,a,ids,quantity=1){const c=configuration(p,a,ids);const options=c.options.map(o=>o.id).filter(x=>x!==undefined).sort();return {key:p.id+':'+options.join(','),profile:p.id,options,quantity};}
function merge(list,e){const existing=list.find(v=>v.key===e.key);if(existing)existing.quantity+=e.quantity;else list.push({...e,options:[...e.options]});}
function addEntry(r,p,a,ids,targetId,quantity=1){if(!Number.isInteger(quantity)||quantity<1||quantity>999)throw Error('Choose a quantity between 1 and 999.');if(!membership(p,a))throw Error('Profile not available in this army.');if(r.army&&r.army!==a.id)throw Error('Your roster uses another army. Clear it before starting a different army.');if(p.unique&&(quantity>1||allEntries(r).some(e=>e.profile===p.id)))throw Error('This unique profile can only appear once.');const e=entry(p,a,ids,quantity);if(p.role==='Hero'){if(quantity!==1)throw Error('Add heroes individually.');const id='wb-'+(r.nextId||1);r.nextId=(r.nextId||1)+1;r.warbands.push({id,hero:e,entries:[]});r.active=id;}else{const w=r.warbands.find(w=>w.id===targetId);if(!w)throw Error('Add a hero and choose a warband first.');merge(w.entries,e);}r.army=a.id;return configuration(p,a,ids);}
function total(r,profiles,armies){const a=armies.find(a=>a.id===r.army);return a?allEntries(r).reduce((sum,e)=>sum+configuration(profiles.find(p=>p.id===e.profile),a,e.options).points*e.quantity,0):0;}
function move(r,sourceId,key,targetId,quantity){const source=sourceId==='unassigned'?r.unassigned:r.warbands.find(w=>w.id===sourceId)?.entries;const target=r.warbands.find(w=>w.id===targetId)?.entries;const e=source?.find(e=>e.key===key);if(!e||!target||source===target||!Number.isInteger(quantity)||quantity<1||quantity>e.quantity)throw Error('Choose a different warband and a valid quantity.');merge(target,{...e,quantity});e.quantity-=quantity;if(!e.quantity)source.splice(source.indexOf(e),1);}
function removeWarband(r,id,targetId=null){const w=r.warbands.find(w=>w.id===id);if(!w)throw Error('Warband not found.');if(targetId){const target=r.warbands.find(w=>w.id===targetId);if(!target||target===w)throw Error('Choose another warband.');w.entries.forEach(e=>merge(target.entries,e));}r.warbands=r.warbands.filter(v=>v.id!==id);if(r.active===id)r.active=r.warbands[0]?.id||null;if(!allEntries(r).length)r.army=null;}
function migrate(old,data){const r={name:old?.name||'Untitled roster',limit:old?.limit||500,army:old?.army||null,warbands:[],unassigned:[],active:null,nextId:1};if(old?.warbands){return old;}const a=data.armies.find(a=>a.id===r.army);if(!a)return {...r,army:null};for(const e of old.entries||[]){const p=data.profiles.find(p=>p.id===e.profile);if(!p)continue;if(p.role==='Hero'){for(let n=0;n<e.quantity;n++){const id='wb-'+r.nextId++;r.warbands.push({id,hero:{...e,quantity:1},entries:[]});}}else r.unassigned.push(e);}r.active=r.warbands[0]?.id||null;return r;}
root.RosterModel={membership,availableOptions,requiredOptions,configuration,addEntry,total,allEntries,warriorCount,capacity,move,removeWarband,migrate};
})(typeof window==='undefined'?globalThis:window);
